import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    op = [h[1] for h in history]
    me = [h[0] for h in history]

    last_op = op[-1]
    last_me = me[-1]

    opp_c = sum(1 for x in op if x == 'C')
    opp_rate = opp_c / n
    rounds_left = 100 - n

    # final round: defect unless opponent has been nearly always cooperative and we've been cooperative
    if rounds_left <= 1:
        if opp_rate > 0.9 and n >= 5:
            return 'C'
        return 'D'

    # endgame: exploit hard
    if rounds_left <= 6:
        if opp_rate > 0.85 and opp_rate > (me.count('D') / n) * 0.5:
            return 'C'
        return 'D'

    # Estimate current streak of opponent actions
    run_o = 1
    i = n - 1
    while i > 0 and op[i - 1] == last_op:
        run_o += 1
        i -= 1

    # Very cooperative opponent: defect occasionally for gain
    if opp_rate > 0.85 and n >= 10:
        # if opponent strictly cooperates (never defected), exploit frequently
        if opp_c == n:
            if rng.random() < 0.55:
                return 'D'
            return 'C'
        # otherwise keep mostly cooperating but probe
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    # Exploitative opponent
    if opp_rate < 0.25:
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # Tit-for-tat with selective forgiveness for isolated defections
    if last_op == 'D':
        # If their overall rate is high but they just defected once, forgive sometimes
        if opp_rate > 0.7 and run_o == 1 and last_me == 'C' and rng.random() < 0.4:
            return 'C'
        # If we've both been defecting for a while, try to break the cycle
        if last_me == 'D' and run_o >= 2 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # last_op == 'C'
    if opp_rate > 0.6:
        # Mostly cooperate; probe rarely except against always-C handled above
        if rng.random() < 0.04:
            return 'D'
        return 'C'

    # Mid-range opponent: cooperate if they just cooperated after defection
    if run_o >= 2:
        return 'C'
    if rng.random() < 0.15:
        return 'D'
    return 'C'
